<script setup lang="ts">
import {ref,onMounted} from 'vue';import {useRoute} from 'vue-router';import {buyer,date,money,mutationKey} from '../../../shared/api';import type {Order} from '../../../shared/types';import {useLoad} from '../../../shared/useLoad';import LoadState from '../components/LoadState.vue';import OrderSummary from '../components/OrderSummary.vue';import ShopCard from '../components/ShopCard.vue'
const route=useRoute(),order=ref<Order>(),confirmCancel=ref(false),showAgreement=ref(false),key=mutationKey(),{loading,error,run}=useLoad();const path=`/orders/${route.params.orderId}`
const load=()=>run(async()=>{order.value=await buyer('GET',path)})
async function cancel(){await run(async()=>{const body={reason:'用户主动取消'};await buyer('POST',path+'/cancel',body,undefined,key(path+'/cancel',body));order.value=await buyer('GET',path);confirmCancel.value=false})}
onMounted(load)
</script>
<template><div class="container page narrow"><RouterLink to="/orders" class="text-link">← 我的预约与订单</RouterLink><LoadState v-if="!order" :loading="loading" :error="error" @retry="load"/><template v-if="order"><div class="section-heading"><h1>{{order.statusText}}</h1><button class="btn secondary" :disabled="loading" @click="load">刷新状态</button></div><p class="muted">订单 {{order.orderNo}} · {{date(order.createdAt)}}</p><OrderSummary :product="order.product" :amount="order.amount"/><div class="panel stack"><p>联系人：{{order.contactName}} · {{order.contactPhoneMasked}}</p><template v-if="order.appointment"><p>预约到店：{{date(order.appointment.visitAt)}}（北京时间）</p><p v-if="order.status==='pending_confirmation'">店长确认截止：{{date(order.expiresAt)}}</p><p v-if="order.status==='reservation_confirmed'">预约已确认，请按时到店。保留至 {{date(order.expiresAt)}}</p><p>线上不扣款，到店付款并交付后由店长登记完成。售后请联系门店。</p><p v-if="order.status==='cancelled'">取消原因：{{order.cancelReason==='user_cancelled'?'你已取消预约':order.cancelReason}}</p><p v-if="order.status==='expired'">预约已过期，宠物占用已释放；可返回宠物页面重新预约。</p></template><p v-else-if="order.status==='pending_paid'">线上支付已停用，请取消旧订单后重新预约，或联系门店。</p><p v-if="order.pickupDeadlineAt">自提截止：{{date(order.pickupDeadlineAt)}}</p><p v-if="order.healthGuaranteeExpiresAt">健康保障截止：{{date(order.healthGuaranteeExpiresAt)}}</p><p v-if="order.refundedAmount">已退款：{{money(order.refundedAmount)}}</p><p v-if="order.remark">备注：{{order.remark}}</p><div class="actions"><RouterLink v-if="order.availableActions.includes('pay')" class="btn" :to="`${path}/payment`">继续支付</RouterLink><RouterLink v-if="order.availableActions.includes('view_pickup')" class="btn" :to="`${path}/pickup`">查看自提凭证</RouterLink><button v-if="order.availableActions.includes('cancel')" class="btn secondary" @click="confirmCancel=true">{{order.appointment?'取消预约':'取消订单'}}</button><RouterLink v-if="order.availableActions.includes('apply_after_sale')" class="btn secondary" :to="`${path}/after-sale`">申请售后</RouterLink><RouterLink v-if="order.afterSale" class="btn secondary" :to="`/after-sales/${order.afterSale.id}`">查看售后进度</RouterLink><button class="text-link" @click="showAgreement=!showAgreement">查看签署协议</button></div><p v-if="error" role="alert" class="error-text">{{error}}</p><article v-if="showAgreement" class="agreement-text"><h3>{{order.agreement.title}}</h3><small>版本 {{order.agreement.version}} · {{date(order.agreement.signedAt)}}</small><p>{{order.agreement.content}}</p></article></div><ShopCard :shop="order.shopSnapshot"/><div v-if="confirmCancel" class="modal-layer" @click.self="confirmCancel=false"><section class="modal compact" role="dialog" aria-modal="true" aria-labelledby="cancel-title"><h2 id="cancel-title">{{order.appointment?'确认取消这次预约？':'确认取消这笔订单？'}}</h2><p>{{order.appointment?'取消后会释放此宠物，其他人可以预约。':'历史支付结果需核实后关闭订单。'}}</p><div class="actions"><button class="btn secondary" @click="confirmCancel=false">保留订单</button><button class="btn" :disabled="loading" @click="cancel">确认取消</button></div></section></div></template></div></template>
